<?php $labels=['first_name'=>'نام','last_name'=>'نام خانوادگی','art_name'=>'نام هنری؛ اختیاری','website'=>'وب‌سایت؛ اختیاری','private_phone'=>'تلفن تماس خصوصی','private_email'=>'ایمیل تماس خصوصی']; ?>
<div class="fields"><?php foreach($labels as $key=>$label): ?><label><?= e($label) ?><input name="<?= e($key) ?>" maxlength="<?= in_array($key,['website'],true)?1000:255 ?>" <?= in_array($key,['first_name','last_name'],true)?'required':'' ?> value="<?= e($v[$key]??'') ?>"></label><?php endforeach ?>
<fieldset class="full"><legend>حوزه فعالیت هنری</legend><div class="artist-checks"><?php foreach($terms as $t):if($t['taxonomy']!=='art_specialty')continue; ?><label class="check"><input type="checkbox" name="specialties[]" value="<?= (int)$t['id'] ?>" <?= in_array((int)$t['id'],array_map('intval',$v['specialties']??[]),true)?'checked':'' ?>><?= e($t['title']) ?></label><?php endforeach ?></div></fieldset>
<?php foreach(['summary'=>'معرفی کوتاه','biography'=>'درباره من و معرفی هنری','awards'=>'سوابق فعالیت','social_links'=>'شبکه‌های اجتماعی؛ هر نشانی در یک خط'] as $key=>$label): ?><label class="full"><?= e($label) ?><textarea name="<?= e($key) ?>" rows="<?= $key==='biography'?5:3 ?>" maxlength="<?= $key==='biography'?20000:($key==='awards'?10000:5000) ?>" <?= $key==='biography'?'required':'' ?>><?= e(is_array($v[$key]??null)?implode("\n",$v[$key]):($v[$key]??'')) ?></textarea></label><?php endforeach ?>
<label class="full">تصویر پروفایل؛ JPG، JPEG، PNG یا WebP<input type="file" name="avatar" accept=".jpg,.jpeg,.png,.webp" <?= !empty($avatarRequired)?'required':'' ?>></label>
<?php if(!empty($application)): ?><label class="full">اطلاعات تماس تکمیلی؛ خصوصی<textarea name="contact_details" maxlength="3000" rows="2"><?= e($v['contact_details']??'') ?></textarea></label><label class="full">لینک نمونه‌کار؛ هر نشانی در یک خط<textarea name="sample_links" maxlength="5000" rows="3"><?= e($v['sample_links']??'') ?></textarea></label><label class="full">نمونه‌کار تصویری؛ حداکثر ۳ فایل در این ارسال<input type="file" name="samples[]" multiple accept=".jpg,.jpeg,.png,.webp"></label><?php endif ?></div><p class="hint">اطلاعات تماس و نمونه‌کارهای درخواست عضویت خصوصی هستند. بارگذاری تصویر پروفایل حداکثر ۴ مگاپیکسل است.</p>
